// Template for frontend/public/config.js.
//
// config.js is GENERATED by deploy.sh Step 9 from CloudFormation stack outputs and is
// gitignored: it contains account-specific identifiers and an API Gateway key, neither
// of which belongs in version control.
//
// For local development against a deployed environment, copy this file to config.js
// and fill in the values, or run deploy.sh and then point the redirect URIs at
// localhost. The localhost URLs must also be registered as allowed callback and
// sign-out URLs on the Cognito app client — pass them via the CallbackURL and
// LogoutURL parameters of cloudformation/gateway-stack.yaml rather than editing the
// client by hand, otherwise the stack and the client drift apart.
//
// Read the deployed values with:
//   aws cloudformation describe-stacks --stack-name ai-gateway-poc \
//     --query 'Stacks[0].Outputs' --output table
window.CONFIG = {
  // Stack output: CognitoDomain
  COGNITO_DOMAIN: 'https://<domain-prefix>.auth.<region>.amazoncognito.com',
  // Stack output: AppClientId
  COGNITO_CLIENT_ID: '<cognito-app-client-id>',
  // Must exactly match a registered callback URL on the app client
  COGNITO_REDIRECT_URI: 'http://localhost:3000/callback',
  // Must exactly match a registered sign-out URL on the app client
  COGNITO_LOGOUT_URI: 'http://localhost:3000',
  // Stack output: GatewayUrl
  API_GATEWAY_URL: 'https://<api-id>.execute-api.<region>.amazonaws.com/v1',
  // API Gateway key for usage-plan tracking. Never commit a real value.
  API_KEY: '<api-key>'
};
